def commonChild(self, s1: str, s2: str) -> int:
    def lcs(i: int, j: int) -> int:
        if i == 0 or j == 0:
            return 0
        if s1[i - 1] == s2[j - 1]:
            return lcs(i - 1, j - 1) + 1
        return max(lcs(i - 1, j), lcs(i, j - 1))
    return lcs(len(s1), len(s2))

